using System;
using BrakeToy.Core;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using Object=UnityEngine.Object;
namespace BrakeToy.Editor
{
    public static class AdventureSceneBuilder
    {
        public const string ScenePath="Assets/BrakeToy/Scenes/ToyRoomAdventure.unity",Root="Assets/BrakeToy/Art/Adventure/";
        private static Material cardboard,cream,red,green,blue,yellow,dark,metal,glass,tape;private static int meshIndex;
        [MenuItem("Tools/Brake Toy/Open Adventure v0.9")]public static void Open(){if(!File.Exists(ScenePath))Create();else EditorSceneManager.OpenScene(ScenePath);}
        public static void Create()
        {
            if(File.Exists(ScenePath))throw new InvalidOperationException("Preserve Adventure scene");foreach(var d in new[]{"Materials","Meshes","Prefabs"})Directory.CreateDirectory(Root+d);AssetDatabase.Refresh();
            var scene=EditorSceneManager.OpenScene(TidySceneBuilder.ScenePath);EditorSceneManager.SaveScene(scene,ScenePath);var g=Object.FindFirstObjectByType<GameManager>();g.name="Brake Toy — Adventure v0.9";var a=g.gameObject.AddComponent<AdventureEncounters>();a.Templates=new AdventureToy[8];
            cardboard=Mat("Corrugated kraft",new Color(.69f,.40f,.19f),.08f);cream=Mat("Printed ivory",new Color(.97f,.89f,.67f),.1f);red=Mat("Cherry plastic",new Color(.91f,.12f,.19f),.42f);green=Mat("Mint plastic",new Color(.16f,.74f,.43f),.4f);blue=Mat("Sky plastic",new Color(.12f,.49f,.86f),.5f);yellow=Mat("Warm yellow",new Color(1,.68f,.06f),.4f);dark=Mat("Soft rubber",new Color(.035f,.045f,.07f),.1f);metal=Mat("Windup metal",new Color(.54f,.64f,.69f),.65f,.75f);glass=Mat("Glossy playing card",new Color(.26f,.83f,.94f),.92f);tape=Mat("Sticky pink tape",new Color(.96f,.34f,.54f),.16f);
            for(int k=0;k<8;k++){var root=new GameObject("Adventure "+(TrackToy)k).transform;var toy=root.gameObject.AddComponent<AdventureToy>();toy.Kind=(TrackToy)k;var solids=new List<AdventureSolid>();Build(toy,solids);toy.Solids=solids.ToArray();Persist(root);a.Templates[k]=PrefabUtility.SaveAsPrefabAsset(root.gameObject,Root+"Prefabs/"+(TrackToy)k+".prefab").GetComponent<AdventureToy>();Object.DestroyImmediate(root.gameObject);}
            g.Arcade.DistanceRecordKey="BrakeToy.v09.distance";g.Arcade.StyleRecordKey="BrakeToy.v09.style";PlayerSettings.bundleVersion="0.9.0";PlayerSettings.Android.bundleVersionCode=10;EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene(ScenePath,true)}.Concat(EditorBuildSettings.scenes.Where(s=>s.path!=ScenePath)).ToArray();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();UpgradeTrain();FinishVariants();Debug.Log("Adventure scene generated: 8 pooled interactive toy families, Tidy preserved.");
        }
        public static void FinishVariants()
        {
            Material Load(string name)=>AssetDatabase.LoadAssetAtPath<Material>(Root+"Materials/"+name+".mat");cardboard=Load("Corrugated kraft");cream=Load("Printed ivory");red=Load("Cherry plastic");green=Load("Mint plastic");blue=Load("Sky plastic");yellow=Load("Warm yellow");dark=Load("Soft rubber");metal=Load("Windup metal");glass=Load("Glossy playing card");tape=Load("Sticky pink tape");
            foreach(int k in new[]{1,2}){var obj=new GameObject("Adventure "+(TrackToy)k);try{var a=obj.AddComponent<AdventureToy>();a.Kind=(TrackToy)k;var solids=new List<AdventureSolid>();Build(a,solids);a.Solids=solids.ToArray();Persist(obj.transform);PrefabUtility.SaveAsPrefabAsset(obj,Root+"Prefabs/"+(TrackToy)k+".prefab");}finally{Object.DestroyImmediate(obj);}}
            var path=Root+"Prefabs/Tunnel.prefab";var tunnel=PrefabUtility.LoadPrefabContents(path);try{var a=tunnel.GetComponent<AdventureToy>();var solids=a.Solids.ToList();if(!solids.Any(s=>s.Centre.y>2))solids.Add(new AdventureSolid{Centre=new Vector3(0,2.08f,1.8f),Half=new Vector3(3.43f,.065f,2.5f)});a.Solids=solids.ToArray();if(a.transform.localScale.y<1.1f){float factor=3.05f/2.08f;a.transform.localScale=new Vector3(1,factor,1);foreach(var solid in a.Solids){solid.Centre.y*=factor;solid.Half.y*=factor;}}PrefabUtility.SaveAsPrefabAsset(tunnel,path);}finally{PrefabUtility.UnloadPrefabContents(tunnel);}AdventurePolish.Apply();AssetDatabase.SaveAssets();
        }
        public static void UpgradeTrain()
        {
            var path=Root+"Prefabs/Train.prefab";var obj=PrefabUtility.LoadPrefabContents(path);try{var a=obj.GetComponent<AdventureToy>();for(int i=0;i<a.Moving.Length;i++){a.Moving[i].localScale=Vector3.one*.45f;a.Moving[i].localRotation=Quaternion.Euler(0,90,0);a.Solids[i].Centre=new Vector3(0,.26f,0);a.Solids[i].Half=new Vector3(.35f,.26f,.22f);}foreach(Transform child in obj.transform.Cast<Transform>().ToArray())if(child.name=="Rail sleeper"||child.name=="Shiny train rail")Object.DestroyImmediate(child.gameObject);var rail=new GameObject("Transverse railway").transform;rail.SetParent(obj.transform,false);var mat=AssetDatabase.LoadAssetAtPath<Material>(Root+"Materials/Windup metal.mat");var wood=AssetDatabase.LoadAssetAtPath<Material>(Root+"Materials/Corrugated kraft.mat");for(int i=0;i<8;i++)Box("Transverse sleeper",rail,new Vector3(i*.34f-1.2f,.025f,0),new Vector3(.08f,.04f,.6f),wood);foreach(float side in new[]{-1f,1f})Box("Transverse rail",rail,new Vector3(0,.05f,side*.14f),new Vector3(2.6f,.045f,.035f),mat);Persist(obj.transform);PrefabUtility.SaveAsPrefabAsset(obj,path);}finally{PrefabUtility.UnloadPrefabContents(obj);}AssetDatabase.SaveAssets();
        }
        private static Material Mat(string name,Color color,float smooth,float metallic=0){var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=name};m.SetColor("_BaseColor",color);m.SetFloat("_Smoothness",smooth);m.SetFloat("_Metallic",metallic);AssetDatabase.CreateAsset(m,Root+"Materials/"+name+".mat");return m;}
        private static Transform Group(string name,Transform parent){var t=new GameObject(name).transform;t.SetParent(parent,false);return t;}
        private static void Box(string name,Transform parent,Vector3 p,Vector3 size,Material m,float r=.035f)=>LivingMeshFactory.Box(name,parent,p,size,m,r);
        private static void Sphere(string name,Transform p,Vector3 at,Vector3 size,Material m)=>LivingMeshFactory.Sphere(name,p,at,size,m);
        private static void Solid(List<AdventureSolid> s,Transform part,Vector3 centre,Vector3 half,bool sphere=false)=>s.Add(new AdventureSolid{Part=part,Centre=centre,Half=half,Sphere=sphere});
        private static void Arrow(Transform parent,float x,float z,Material m)
        {var mesh=new Mesh();mesh.vertices=new[]{new Vector3(-.12f,0,-.7f),new Vector3(.12f,0,-.7f),new Vector3(.12f,0,0),new Vector3(.36f,0,0),new Vector3(0,0,.48f),new Vector3(-.36f,0,0),new Vector3(-.12f,0,0)};mesh.triangles=new[]{0,2,1,0,6,2,6,4,2,6,5,4,2,4,3};mesh.RecalculateNormals();LivingMeshFactory.MeshObject("Printed route arrow",parent,mesh,m,new Vector3(x,.079f,z));}
        private static void Eyes(Transform t,float z,float y){foreach(float side in new[]{-1f,1f}){Sphere("White eye",t,new Vector3(side*.19f,y,z),new Vector3(.19f,.21f,.13f),cream);Sphere("Pupil",t,new Vector3(side*.19f,y+.01f,z-.065f),new Vector3(.08f,.1f,.045f),dark);}}
        private static void Wheels(Transform t,float halfZ){foreach(float side in new[]{-1f,1f})foreach(float z in new[]{-halfZ,halfZ}){Sphere("Turning rubber wheel",t,new Vector3(side*.37f,.18f,z),new Vector3(.15f,.32f,.32f),dark);Sphere("Wheel hub",t,new Vector3(side*.45f,.18f,z),Vector3.one*.13f,yellow);}}
        private static void Vehicle(Transform t,bool train,bool engine=false)
        {Box("Toy chassis",t,new Vector3(0,.26f,0),new Vector3(.85f,.2f,1.45f),red);Wheels(t,.43f);if(train){Box(engine?"Locomotive cab":"Open wagon",t,new Vector3(0,.62f,-.25f),new Vector3(.72f,.58f,engine?.6f:1.12f),engine?blue:green);if(engine){Sphere("Boiler",t,new Vector3(0,.57f,.35f),new Vector3(.65f,.55f,.65f),yellow);Box("Chimney",t,new Vector3(0,.97f,.4f),new Vector3(.23f,.48f,.23f),dark);}else Sphere("Cargo ball",t,new Vector3(0,1,.05f),Vector3.one*.5f,yellow);Box("Cab roof",t,new Vector3(0,1,-.27f),new Vector3(.87f,.09f,.72f),red);Box("Coupler",t,new Vector3(0,.22f,.88f),new Vector3(.13f,.13f,.3f),metal);}else{Box("Cabin",t,new Vector3(0,.53f,-.12f),new Vector3(.66f,.35f,.65f),blue);Box("Windshield",t,new Vector3(0,.56f,-.46f),new Vector3(.53f,.21f,.025f),glass);foreach(float s in new[]{-1f,1f})Sphere("Warning headlights",t,new Vector3(s*.25f,.35f,-.74f),new Vector3(.16f,.12f,.04f),cream);}}
        private static void Build(AdventureToy a,List<AdventureSolid> s)
        {
            var t=a.transform;var moving=new List<Transform>();
            switch(a.Kind)
            {
                case TrackToy.Tunnel:
                    // Three visible arches: one blocked display, two usable exits. No hidden lane walls.
                    for(int i=0;i<3;i++){var wall=Group("Blocked exit "+i,t);wall.localPosition=new Vector3((i-1)*2.25f,0,0);Box("Folded closed carton",wall,new Vector3(0,.75f,4.3f),new Vector3(1.9f,1.5f,.2f),cardboard);Box("Cross tape",wall,new Vector3(0,.75f,4.18f),new Vector3(1.7f,.13f,.02f),red);moving.Add(wall);Solid(s,wall,new Vector3(0,.75f,4.3f),new Vector3(.95f,.75f,.1f));}
                    foreach(float x in new[]{-3.375f,-1.125f,1.125f,3.375f}){Box("Cardboard arch upright",t,new Vector3(x,1.02f,1.8f),new Vector3(.11f,2.04f,5),cardboard);Solid(s,null,new Vector3(x,1.02f,1.8f),new Vector3(.055f,1.02f,2.5f));for(int n=0;n<4;n++)Box("Corrugated edge",t,new Vector3(x,1.95f-n*.035f,-.72f),new Vector3(.13f,.012f,.025f),cream,.003f);}
                    Box("Carton roof",t,new Vector3(0,2.08f,1.8f),new Vector3(6.86f,.13f,5),cardboard);Solid(s,null,new Vector3(0,2.08f,1.8f),new Vector3(3.43f,.065f,2.5f));Box("Roof parcel tape",t,new Vector3(0,2.153f,1.8f),new Vector3(.32f,.018f,5),cream);
                    for(int lane=0;lane<3;lane++)Arrow(t,(lane-1)*2.25f,-1.8f,green);break;
                case TrackToy.Windup:
                    var pivot=Group("Windup motion",t);moving.Add(pivot);var duck=Group("Walking duck",pivot);var frog=Group("Hopping frog",pivot);a.Options=new[]{duck,frog};Sphere("Rounded toy body",duck,new Vector3(0,.38f,0),new Vector3(.9f,.64f,1.0f),yellow);Sphere("Head",duck,new Vector3(0,.73f,-.32f),new Vector3(.62f,.55f,.57f),yellow);Eyes(duck,-.60f,.79f);Box("Orange beak",duck,new Vector3(0,.65f,-.70f),new Vector3(.45f,.12f,.28f),red);foreach(float side in new[]{-1f,1f}){Box("Foot",duck,new Vector3(side*.25f,.07f,-.14f),new Vector3(.25f,.1f,.55f),red);Sphere("Wing",duck,new Vector3(side*.43f,.42f,.08f),new Vector3(.12f,.35f,.58f),cream);}Box("Windup key stem",duck,new Vector3(.55f,.5f,.12f),new Vector3(.30f,.06f,.06f),metal);foreach(float y in new[]{.39f,.61f})Sphere("Windup key bow",duck,new Vector3(.73f,y,.12f),new Vector3(.16f,.17f,.10f),metal);Sphere("Frog body",frog,new Vector3(0,.31f,.05f),new Vector3(.86f,.48f,.76f),green);Sphere("Frog head",frog,new Vector3(0,.62f,-.25f),new Vector3(.80f,.44f,.48f),green);foreach(float side in new[]{-1f,1f}){Sphere("Raised frog eye",frog,new Vector3(side*.25f,.83f,-.37f),new Vector3(.24f,.24f,.18f),cream);Sphere("Frog pupil",frog,new Vector3(side*.25f,.83f,-.46f),new Vector3(.11f,.14f,.035f),dark);Box("Frog foreleg",frog,new Vector3(side*.28f,.18f,-.22f),new Vector3(.14f,.30f,.20f),green);Box("Frog forefoot",frog,new Vector3(side*.34f,.05f,-.36f),new Vector3(.23f,.08f,.4f),green);Sphere("Folded hind leg",frog,new Vector3(side*.34f,.16f,.25f),new Vector3(.30f,.28f,.48f),green);}Box("Frog smile",frog,new Vector3(0,.53f,-.49f),new Vector3(.36f,.025f,.02f),dark);Box("Frog windup key",frog,new Vector3(.55f,.4f,.1f),new Vector3(.35f,.07f,.08f),metal);Solid(s,pivot,new Vector3(0,.48f,-.08f),new Vector3(.46f,.48f,.65f));break;
                case TrackToy.Crane:
                    foreach(float side in new[]{-1f,1f}){Box("Crane tower",t,new Vector3(side*.85f,1.6f,1.4f),new Vector3(.13f,3.2f,.22f),yellow);Solid(s,null,new Vector3(side*.85f,1.6f,1.4f),new Vector3(.065f,1.6f,.11f));}Box("Crane crossbeam",t,new Vector3(0,3.18f,1.4f),new Vector3(1.92f,.18f,.3f),yellow);Box("Crane forward boom",t,new Vector3(0,3.18f,.7f),new Vector3(.18f,.18f,1.4f),yellow);var load=Group("Swinging soft toy load",t);moving.Add(load);Box("Soft parcel",load,Vector3.zero,new Vector3(.66f,.62f,.65f),blue,.11f);Box("Parcel ribbon",load,new Vector3(0,0,-.33f),new Vector3(.12f,.63f,.02f),cream);Eyes(load,-.345f,.08f);Solid(s,load,Vector3.zero,new Vector3(.33f,.31f,.325f));a.Shadow=Group("Readable load shadow",t);Sphere("Shadow disk",a.Shadow,Vector3.zero,new Vector3(.75f,.012f,.75f),dark);a.Link=Group("Tension rope",t);Box("Crane cord",a.Link,Vector3.zero,new Vector3(.035f,1,.035f),dark,.008f);break;
                case TrackToy.Train:
                    for(int i=0;i<3;i++){var car=Group(i==0?"Toy locomotive":"Coupled wagon "+i,t);moving.Add(car);Vehicle(car,true,i==0);car.localScale=Vector3.one*.45f;car.localRotation=Quaternion.Euler(0,90,0);Solid(s,car,new Vector3(0,.26f,0),new Vector3(.35f,.26f,.22f));}Signal(t,a,"Rail crossing signal");for(int i=0;i<8;i++){Box("Rail sleeper",t,new Vector3(0,.024f,i*1.1f-.6f),new Vector3(1.9f,.045f,.15f),cardboard);foreach(float side in new[]{-1f,1f})Box("Shiny train rail",t,new Vector3(side*.31f,.055f,i*1.1f-.6f),new Vector3(.045f,.045f,1.12f),metal);}break;
                case TrackToy.Marbles:
                    for(int i=0;i<3;i++){var ball=Group("Marble rolling rig "+i,t);moving.Add(ball);Sphere("Glass marble",ball,Vector3.zero,Vector3.one*.58f,i==0?blue:i==1?red:yellow);foreach(float side in new[]{-1f,1f})Sphere("Marble swirl",ball,new Vector3(side*.15f,.01f,-.22f),new Vector3(.10f,.34f,.08f),cream);Solid(s,ball,Vector3.zero,Vector3.one*.29f,true);}foreach(float side in new[]{-1f,1f})Box("Chute side",t,new Vector3(side*.55f,.4f,9),new Vector3(.12f,.8f,2.1f),blue);Box("Chute base",t,new Vector3(0,.12f,9),new Vector3(1.1f,.15f,2.1f),yellow);Arrow(t,0,7,cream);break;
                case TrackToy.Surfaces:
                    var sticky=Group("Sticky band",t);var ice=Group("Glossy cards",t);a.Options=new[]{sticky,ice};Box("Pink tape patch",sticky,new Vector3(0,.018f,0),new Vector3(1.7f,.03f,6),tape);for(int n=0;n<5;n++)Box("Adhesive grooves",sticky,new Vector3(0,.038f,n*1.1f-2.2f),new Vector3(1.55f,.008f,.022f),cream,.003f);for(int n=0;n<3;n++){Box("Playing card",ice,new Vector3(0,.02f,n*1.9f-1.9f),new Vector3(1.7f,.035f,1.8f),cream);Box("Glossy cyan print",ice,new Vector3(0,.043f,n*1.9f-1.9f),new Vector3(1.45f,.012f,1.55f),glass);Sphere("Card pip",ice,new Vector3(0,.055f,n*1.9f-1.9f),new Vector3(.42f,.008f,.42f),red);}break;
                case TrackToy.Seesaw:
                    var ruler=Group("Tilting ruler",t);moving.Add(ruler);Box("Wooden ruler",ruler,Vector3.zero,new Vector3(1.7f,.08f,5.2f),cream);for(int i=0;i<25;i++)Box("Ruler graduation",ruler,new Vector3(-.5f,.045f,-2.4f+i*.2f),new Vector3(i%5==0?.55f:.26f,.01f,.022f),dark,.003f);Box("Pivot block",t,new Vector3(0,.13f,0),new Vector3(1.1f,.26f,.42f),red);Arrow(t,0,-3.7f,green);break;
                case TrackToy.Garage:
                    foreach(float side in new[]{-1f,1f}){Box("Toy garage upright",t,new Vector3(side*.91f,.9f,0),new Vector3(.16f,1.8f,.28f),blue);Solid(s,null,new Vector3(side*.91f,.9f,0),new Vector3(.08f,.9f,.14f));}Box("Garage roof",t,new Vector3(0,1.86f,.5f),new Vector3(2,.16f,1.6f),red);var shutter=Group("Lifting garage shutter",t);moving.Add(shutter);Box("Ribbed door",shutter,new Vector3(0,.78f,0),new Vector3(1.65f,1.56f,.15f),yellow);for(int i=0;i<6;i++)Box("Door rib",shutter,new Vector3(0,.14f+i*.25f,-.09f),new Vector3(1.6f,.025f,.03f),cream);Solid(s,shutter,new Vector3(0,.78f,0),new Vector3(.825f,.78f,.075f));for(int i=1;i<3;i++){var car=Group("Emerging toy car "+i,t);moving.Add(car);Vehicle(car,false);Solid(s,car,new Vector3(0,.45f,0),new Vector3(.45f,.45f,.75f));}Signal(t,a,"Garage warning lights");break;
            }
            a.Moving=moving.ToArray();
        }
        private static void Signal(Transform t,AdventureToy a,string name){var signal=Group(name,t);signal.localPosition=new Vector3(-.8f,1.5f,-2);Sphere("Warning lamp",signal,Vector3.zero,Vector3.one*.27f,red);Box("Signal post",t,new Vector3(-.8f,.7f,-2),new Vector3(.08f,1.4f,.08f),cream);a.Signal=signal;}
        private static void Persist(Transform t){foreach(var f in t.GetComponentsInChildren<MeshFilter>(true))if(f.sharedMesh&&!EditorUtility.IsPersistent(f.sharedMesh))AssetDatabase.CreateAsset(f.sharedMesh,AssetDatabase.GenerateUniqueAssetPath(Root+"Meshes/Part_"+meshIndex+++".asset"));}
    }
}
